import{_ as r,C as i,o as t,c as o,a2 as a,b as l,w as s,a as d,E as c,a3 as h}from"./chunks/framework.Brv5O9VI.js";const b=JSON.parse('{"title":"14.6 Caching Strategy & Vector Optimization","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.6-caching.md","filePath":"system-design/14.6-caching.md"}'),m={name:"system-design/14.6-caching.md"};function g(u,e,p,y,f,C){const n=i("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="_14-6-caching-strategy-vector-optimization" tabindex="-1">14.6 Caching Strategy &amp; Vector Optimization <a class="header-anchor" href="#_14-6-caching-strategy-vector-optimization" aria-label="Permalink to &quot;14.6 Caching Strategy &amp; Vector Optimization&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Caching stores the results of computationally expensive operations (such as transformer vector calculations or database queries) in ultra-fast volatile memory (RAM or Redis) so subsequent identical requests are resolved in sub-millisecond times.</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How THIS Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How THIS Project Uses It&quot;">​</a></h2><ul><li><strong>Resident In-Memory Model Cache</strong>: The largest bottleneck in RAG systems is neural network embedding generation (~14ms). The backend loads FastEmbed and FAISS pointers permanently into process memory ([<code>app.py:L24-L29</code>](file:///Users/avishjain/avishjain9-repos/21-bis-compliance-engine/app.py#L24-L29)), ensuring that models are never re-initialized per request.</li><li><strong>Dynamic Query Cache</strong>: <strong>Not explicitly implemented in code</strong> (currently re-embeds incoming queries). This was a conscious decision for the current scale, as 14ms is well within acceptable real-time UX thresholds (&lt;100ms) [CONFIRM WITH DEVELOPER].</li></ul>',6)),(t(),l(h,null,{default:s(()=>[c(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Query%5B%22Incoming%20User%20Query%22%5D%20--%3E%20Hash%5B%22Compute%20SHA-256(Query%20Text)%22%5D%0A%20%20%20%20Hash%20--%3E%20CacheCheck%7B%22Cache%20Hit%20in%20Redis%3F%22%7D%0A%20%20%20%20CacheCheck%20--%3E%7CYes%20(Hit)%7C%20CachedVec%5B%22Return%20Cached%20384d%20Vector%20(0.4ms)%22%5D%0A%20%20%20%20CacheCheck%20--%3E%7CNo%20(Miss)%7C%20FastEmbed%5B%22Compute%20FastEmbed%20ONNX%20(14ms)%22%5D%0A%20%20%20%20FastEmbed%20--%3E%20SaveCache%5B%22Store%20in%20Redis%20(TTL%3A%207%20Days)%22%5D%0A%20%20%20%20CachedVec%20--%3E%20FAISS%5B%22Search%20FAISS%20IndexFlatIP%22%5D%0A%20%20%20%20SaveCache%20--%3E%20FAISS%0A%20%20%20%20FAISS%20--%3E%20Resp%5B%22Return%20Matched%20Standard%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-comparison-with-caching-alternatives" tabindex="-1">3. Comparison with Caching Alternatives <a class="header-anchor" href="#_3-comparison-with-caching-alternatives" aria-label="Permalink to &quot;3. Comparison with Caching Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Caching Layer</th><th style="text-align:left;">Implementation</th><th style="text-align:left;">Cache Hit Latency</th><th style="text-align:left;">Invalidation Strategy</th><th style="text-align:left;">Fit for This Engine</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>In-Memory Pre-Loaded Weights</strong> (Used)</td><td style="text-align:left;">Global Python pointers</td><td style="text-align:left;"><strong>0.00 ms (Zero overhead)</strong></td><td style="text-align:left;">Process restart</td><td style="text-align:left;"><strong>Optimal for core models</strong></td></tr><tr><td style="text-align:left;"><strong>Local LRU Cache (<code>functools</code>)</strong></td><td style="text-align:left;">In-process Python dictionary</td><td style="text-align:left;">~0.01 ms</td><td style="text-align:left;">LRU eviction (maxsize=1024)</td><td style="text-align:left;">Highly recommended quick win</td></tr><tr><td style="text-align:left;"><strong>Distributed Redis Cache</strong></td><td style="text-align:left;">Standalone Redis cluster</td><td style="text-align:left;">~0.8 - 1.5 ms</td><td style="text-align:left;">TTL + Key-based invalidation</td><td style="text-align:left;">Recommended for 100x scale</td></tr><tr><td style="text-align:left;"><strong>CDN Edge Caching (Cloudflare)</strong></td><td style="text-align:left;">Edge HTTP headers</td><td style="text-align:left;">~10 - 25 ms</td><td style="text-align:left;">Stale-while-revalidate</td><td style="text-align:left;">Not suited for POST payloads</td></tr></tbody></table><hr><h2 id="_4-trade-offs-accepted" tabindex="-1">4. Trade-offs Accepted <a class="header-anchor" href="#_4-trade-offs-accepted" aria-label="Permalink to &quot;4. Trade-offs Accepted&quot;">​</a></h2><ul><li><strong>Redundant Embedding Compute</strong>: Identical frequent queries (e.g., users repeatedly typing &quot;Ordinary Portland Cement 53 Grade&quot;) incur the full 14ms ONNX CPU cycle every time instead of returning a cached vector in 0.05ms.</li></ul><hr><h2 id="_5-what-breaks-at-scale" tabindex="-1">5. What Breaks at Scale <a class="header-anchor" href="#_5-what-breaks-at-scale" aria-label="Permalink to &quot;5. What Breaks at Scale&quot;">​</a></h2><ul><li><strong>At 10x Load</strong>: Compute overhead remains manageable on multi-core servers.</li><li><strong>At 100x Load</strong>: Repeating the 14ms embedding step across thousands of concurrent queries creates severe CPU throttling.</li><li><strong>At 1000x Load</strong>: Lack of caching causes catastrophic request queueing, ballooning latency past 3 seconds.</li></ul><hr><h2 id="_6-how-a-senior-engineer-would-improve-it" tabindex="-1">6. How a Senior Engineer Would Improve It <a class="header-anchor" href="#_6-how-a-senior-engineer-would-improve-it" aria-label="Permalink to &quot;6. How a Senior Engineer Would Improve It&quot;">​</a></h2><p>Implement a <strong>two-tier cache-aside architecture</strong>:</p><ol><li><strong>L1 Local Cache</strong>: Python&#39;s <code>@functools.lru_cache(maxsize=2048)</code> to cache normalized vector arrays in memory.</li><li><strong>L2 Distributed Cache</strong>: A Redis instance caching <code>{sha256(query): vector_array}</code> with a 30-day Time-To-Live (TTL). Cache hits bypass FastEmbed completely, dropping total query latency from 16ms to <strong>under 1.5ms</strong>.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Currently, our models and FAISS indexes are permanently pre-warmed in resident RAM, avoiding cold-start overhead. To scale past a hundred queries a second, we would implement a Redis cache-aside pattern on the raw query text: caching the 384-dimensional embeddings for the top five thousand product terms drops our inference time from fourteen milliseconds down to under one millisecond on cache hits.&quot;</p></blockquote>',16))])}const x=r(m,[["render",g]]);export{b as __pageData,x as default};
